macro_rules! param_env_with_gat_bounds {
    () => {
        # [doc = " Install projection predicates that allow GATs to project to their own"] # [doc = " definition types. This is not allowed in general in cases of default"] # [doc = " associated types in trait definitions, or when specialization is involved,"] # [doc = " but is needed when checking these definition types actually satisfy the"] # [doc = " trait bounds of the GAT."] # [doc = ""] # [doc = " # How it works"] # [doc = ""] # [doc = " ```ignore (example)"] # [doc = " impl<A, B> Foo<u32> for (A, B) {"] # [doc = "     type Bar<C> = Wrapper<A, B, C>"] # [doc = " }"] # [doc = " ```"] # [doc = ""] # [doc = " - `impl_trait_ref` would be `<(A, B) as Foo<u32>>`"] # [doc = " - `normalize_impl_ty_args` would be `[A, B, ^0.0]` (`^0.0` here is the bound var with db 0 and index 0)"] # [doc = " - `normalize_impl_ty` would be `Wrapper<A, B, ^0.0>`"] # [doc = " - `rebased_args` would be `[(A, B), u32, ^0.0]`, combining the args from"] # [doc = "    the *trait* with the generic associated type parameters (as bound vars)."] # [doc = ""] # [doc = " A note regarding the use of bound vars here:"] # [doc = " Imagine as an example"] # [doc = " ```"] # [doc = " trait Family {"] # [doc = "     type Member<C: Eq>;"] # [doc = " }"] # [doc = ""] # [doc = " impl Family for VecFamily {"] # [doc = "     type Member<C: Eq> = i32;"] # [doc = " }"] # [doc = " ```"] # [doc = " Here, we would generate"] # [doc = " ```ignore (pseudo-rust)"] # [doc = " forall<C> { Normalize(<VecFamily as Family>::Member<C> => i32) }"] # [doc = " ```"] # [doc = ""] # [doc = " when we really would like to generate"] # [doc = " ```ignore (pseudo-rust)"] # [doc = " forall<C> { Normalize(<VecFamily as Family>::Member<C> => i32) :- Implemented(C: Eq) }"] # [doc = " ```"] # [doc = ""] # [doc = " But, this is probably fine, because although the first clause can be used with types `C` that"] # [doc = " do not implement `Eq`, for it to cause some kind of problem, there would have to be a"] # [doc = " `VecFamily::Member<X>` for some type `X` where `!(X: Eq)`, that appears in the value of type"] # [doc = " `Member<C: Eq> = ....` That type would fail a well-formedness check that we ought to be doing"] # [doc = " elsewhere, which would check that any `<T as Family>::Member<X>` meets the bounds declared in"] # [doc = " the trait (notably, that `X: Eq` and `T: Family`)."] fn param_env_with_gat_bounds < 'tcx > (tcx : TyCtxt < 'tcx > , impl_ty : ty :: AssocItem , impl_trait_ref : ty :: TraitRef < 'tcx > ,) -> ty :: ParamEnv < 'tcx > { let param_env = tcx . param_env (impl_ty . def_id) ; let container_id = impl_ty . container_id (tcx) ; let mut predicates = param_env . caller_bounds () . to_vec () ; let impl_tys_to_install = match impl_ty . kind { ty :: AssocKind :: Type { data : ty :: AssocTypeData :: Rpitit (ty :: ImplTraitInTraitData :: Impl { fn_def_id } | ty :: ImplTraitInTraitData :: Trait { fn_def_id , .. } ,) , } => tcx . associated_types_for_impl_traits_in_associated_fn (fn_def_id) . iter () . map (| def_id | tcx . associated_item (* def_id)) . collect () , _ => vec ! [impl_ty] , } ; for impl_ty in impl_tys_to_install { let trait_ty = match impl_ty . container { ty :: AssocContainer :: InherentImpl => bug ! () , ty :: AssocContainer :: Trait => impl_ty , ty :: AssocContainer :: TraitImpl (Err (_)) => continue , ty :: AssocContainer :: TraitImpl (Ok (trait_item_def_id)) => { tcx . associated_item (trait_item_def_id) } } ; let mut bound_vars : smallvec :: SmallVec < [ty :: BoundVariableKind ; 8] > = smallvec :: SmallVec :: with_capacity (tcx . generics_of (impl_ty . def_id) . own_params . len ()) ; let normalize_impl_ty_args = ty :: GenericArgs :: identity_for_item (tcx , container_id) . extend_to (tcx , impl_ty . def_id , | param , _ | match param . kind { GenericParamDefKind :: Type { .. } => { let kind = ty :: BoundTyKind :: Param (param . def_id) ; let bound_var = ty :: BoundVariableKind :: Ty (kind) ; bound_vars . push (bound_var) ; Ty :: new_bound (tcx , ty :: INNERMOST , ty :: BoundTy { var : ty :: BoundVar :: from_usize (bound_vars . len () - 1) , kind } ,) . into () } GenericParamDefKind :: Lifetime => { let kind = ty :: BoundRegionKind :: Named (param . def_id) ; let bound_var = ty :: BoundVariableKind :: Region (kind) ; bound_vars . push (bound_var) ; ty :: Region :: new_bound (tcx , ty :: INNERMOST , ty :: BoundRegion { var : ty :: BoundVar :: from_usize (bound_vars . len () - 1) , kind , } ,) . into () } GenericParamDefKind :: Const { .. } => { let bound_var = ty :: BoundVariableKind :: Const ; bound_vars . push (bound_var) ; ty :: Const :: new_bound (tcx , ty :: INNERMOST , ty :: BoundConst { var : ty :: BoundVar :: from_usize (bound_vars . len () - 1) } ,) . into () } }) ; let normalize_impl_ty = tcx . type_of (impl_ty . def_id) . instantiate (tcx , normalize_impl_ty_args) ; let rebased_args = normalize_impl_ty_args . rebase_onto (tcx , container_id , impl_trait_ref . args) ; let bound_vars = tcx . mk_bound_variable_kinds (& bound_vars) ; match normalize_impl_ty . kind () { ty :: Alias (ty :: Projection , proj) if proj . def_id == trait_ty . def_id && proj . args == rebased_args => { } _ => predicates . push (ty :: Binder :: bind_with_vars (ty :: ProjectionPredicate { projection_term : ty :: AliasTerm :: new_from_args (tcx , trait_ty . def_id , rebased_args ,) , term : normalize_impl_ty . into () , } , bound_vars ,) . upcast (tcx) ,) , } ; } ty :: ParamEnv :: new (tcx . mk_clauses (& predicates)) }
    };
}

param_env_with_gat_bounds!()